  static readonly Slot[] Pool=new Slot[8];static int _epoch;static long _serial;static Material _material;static Texture2D _texture;static Color[] _roles;static Color _lightColor;static readonly MaterialPropertyBlock Props=new MaterialPropertyBlock();
  internal static float MonkReceiveScale=.08f;
  internal static JArray CaptureReviewState(){var rows=new JArray();foreach(var s in Pool)if(s?.Active!=null){var draws=new JArray();foreach(var d in s.Active.Draws){float alpha=0;foreach(var c in d.Colors)alpha+=c.a;draws.Add(new JObject{["active"]=d.Renderer.enabled&&d.Renderer.gameObject.activeInHierarchy,["alphaSum"]=alpha,["vertices"]=d.Vertices.Length});}rows.Add(new JObject{["cacheId"]=System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(s.Active.Geometry),["rootId"]=s.Root.GetEntityId().ToString(),["busy"]=s.Busy,["rootActive"]=s.Root.gameObject.activeInHierarchy,["landed"]=s.Landed,["age"]=Time.time-s.Started,["draws"]=draws});}return rows;}
  public static string LastFailure{get;private set;}public static int Submitted{get;private set;}public static int Recycled{get;private set;}public static int StaleContacts{get;private set;}
  public static int ActiveCount{get{int n=0;foreach(var s in Pool)if(s!=null&&s.Busy)n++;return n;}}
  public static bool IsFamily(string family)=>family=="heal_uplift";
  public static bool Eligible(ResolvedCombatFx.Ticket t)=>t!=null&&IsFamily(t.AttackFamily)&&t.Element=="heal" && t.Outcome=="heal" && t.Amount>0;
  public static float Lead(ResolvedCombatFx.Ticket t)=>Eligible(t)?(float)HealContinuousGeometry.Lead():0;
